const LOCALES = { en: EN }

function enT(key, ...args) {
  const v = key.split('.').reduce((n, p) => (n && typeof n === 'object' ? n[p] : undefined), EN)
  return typeof v === 'function' ? v(...args) : typeof v === 'string' ? v : key
}
const useT = () => usePluginI18n(ID)

// --- shared bits ---------------------------------------------------------------

// The approved cairn render (preflight §2, §5), never redrawn.
function Cairn({ size = 32 }) {
  return CAIRN
    ? jsx('img', { className: 'isc-cairn', src: `data:image/png;base64,${CAIRN}`, width: size, height: size, alt: '', 'aria-hidden': true, draggable: false })
    : null
}

const COUNT_KEYS = ['emotionalCheckIns', 'journalEntries', 'habitsCompleted', 'tasksCompleted', 'itemsCaptured']
const VALENCES = ['pleasant', 'neutral', 'unpleasant']

// The backend answers {ok:false,error} when Innerscape refuses; turn that into a throw.
const okOr = r => { if (!r || r.ok !== true) throw new Error(r?.error || 'no answer'); return r }
const parseTags = s => [...new Set(String(s).split(',').map(x => x.trim()).filter(Boolean))]
const when = ts => { const ms = typeof ts === 'number' ? ts : Date.parse(ts); return Number.isFinite(ms) ? relativeTime(ms) : '' }
const fail = what => err => host.notifyError(err, what)

// Drafts live in memory only: they survive moving around the app, never a restart.
const blankCheckin = () => ({ energy: 50, valence: '', feeling: '', body: '' })
const blankDrafts = () => ({ checkin: blankCheckin(), journal: '', tags: '', stuck: '' })
const drafts = atom(blankDrafts())
const focusTarget = atom(null)

function connState(s) {
  if (!s) return null
  if (String(s.base_url || '').startsWith('invalid')) return 'server'
  if (s.token_set === false || s.ok === false) return 'token'
  if (typeof s.token_expires_in_hours === 'number' && s.token_expires_in_hours <= 0) return 'expired'
  if (s.server && s.server !== 'up') return 'server'
  if (typeof s.token_expires_in_hours === 'number' && s.token_expires_in_hours < 24) return 'soon'
  return 'ok'
}

// The coach runs in chat, where the innerscape:unstuck skill and the tools live.
// Open a fresh chat and put the note in its composer; the user reads it and
// presses send. The composer mounts a moment after newChat, so retry briefly.
// One transfer at a time, owned by the plugin, not the card: navigating to the
// chat unmounts the card, so a card-scoped op would die mid-flight. Disposing
// the plugin bumps `transferSeq`, which cancels any transfer still retrying.
// A destination that already holds other text is never overwritten.
const coachPrompt = (raw, t) => { const r = String(raw).trim(); return r ? t('coach.prompt', r) : t('coach.starter') }
const sleep = ms => new Promise(r => setTimeout(r, ms))
let transferSeq = 0
const transfer = atom(null) // {id, source}: the open op, so the busy state survives a remount
async function handToCoach(text, { tries = 30, wait = 150, op = transferSeq } = {}) {
  if (typeof host.newChat !== 'function' || typeof host.composer?.setDraft !== 'function') return 'miss'
  host.newChat()
  for (let i = 0; i < tries; i++) {
    await sleep(wait)
    if (op !== transferSeq) return 'cancelled'
    try {
      const have = typeof host.composer.getDraft === 'function' ? await host.composer.getDraft('new') : null
      if (op !== transferSeq) return 'cancelled'
      if (have && have.trim() && have !== text) return 'taken'
      if (have === text) return 'ok'
      if (await host.composer.setDraft('new', text)) return op === transferSeq ? 'ok' : 'cancelled'
    } catch {}
  }
  return 'miss'
}
async function startCoach(source, t) {
  if (transfer.get()) return
  const op = transferSeq
  const id = {}
  transfer.set({ id, source })
  let res
  try { res = await handToCoach(coachPrompt(source, t), { op }) } catch { res = 'miss' } finally { if (transfer.get()?.id === id) transfer.set(null) }
  if (res === 'cancelled' || op !== transferSeq) return
  if (res === 'ok') {
    // Clear only the words that were handed over; anything typed since stays.
    if (drafts.get().stuck === source) drafts.set({ ...drafts.get(), stuck: '' })
    return
  }
  // The new chat is on screen now, so bring the user back to their words.
  focusTarget.set('stuck')
  host.navigate(PATH)
  const msg = t(res === 'taken' ? 'err.coachTaken' : 'err.coach')
  host.notifyError(new Error(msg), msg)
}

// --- page ------------------------------------------------------------------------

function Today({ q, t }) {
  const d = q.data
  if (!d) {
    return q.isError
      ? jsxs('p', { className: 'isc-p', role: 'alert', children: [t('err.today'), ' ', jsx(Button, { size: 'xs', variant: 'secondary', onClick: () => q.refetch(), children: t('err.retry') })] })
      : jsx(Skeleton, { style: { height: 120, borderRadius: 10 } })
  }
  if (d.ok === false) return jsx('p', { className: 'isc-p', role: 'alert', children: d.error || t('err.today') })
  const counts = d.counts && typeof d.counts === 'object' ? d.counts : {}
  const c = d.latest_checkin
  const energy = Number.isFinite(Number(c?.energy)) ? Math.max(0, Math.min(100, Number(c.energy))) : null
  return jsxs('div', { className: 'isc-today', children: [
    jsx('ul', { className: 'isc-counts', 'aria-label': t('today.counts'), children: COUNT_KEYS.filter(k => Number.isInteger(counts[k])).map(k =>
      jsxs('li', { className: 'isc-count', children: [jsx('b', { children: counts[k] }), jsx('span', { children: t(`today.${k}`) })] }, k)) }),
    jsxs('div', { className: 'isc-latest', children: [
      jsxs('div', { className: 'isc-latest-top', children: [
        jsx('h3', { className: 'isc-label', style: { margin: 0 }, children: t('today.latest') }),
        c?.at ? jsx('span', { className: 'isc-hint', children: t('today.at', when(c.at)) }) : null
      ] }),
      c
        ? jsxs(Fragment, { children: [
            c.feeling ? jsx('p', { className: 'isc-feel', children: `“${c.feeling}”` }) : null,
            jsxs('ul', { className: 'isc-facts', children: [
              VALENCES.includes(c.valence) ? jsxs('li', { children: [t('today.felt'), ' ', jsx('b', { children: t(`valence.${c.valence}`).toLowerCase() })] }) : null,
              energy !== null ? jsxs('li', { className: 'isc-energy', style: { flex: '1 1 180px' }, children: [
                jsx('span', { children: t('today.energy') }),
                jsx('span', { className: 'isc-energy-bar', 'aria-hidden': true, children: jsx('i', { style: { width: `${energy}%` } }) }),
                jsx('b', { children: t('today.energyOf', energy) })
              ] }) : null
            ] })
          ] })
        : jsx('p', { className: 'isc-p', children: d.latest_checkin_note ? t('today.inferred') : t('today.none') })
    ] })
  ] })
}

function CheckInForm({ ctx, t, onSaved }) {
  const d = useValue(drafts).checkin
  const set = patch => drafts.set({ ...drafts.get(), checkin: { ...drafts.get().checkin, ...patch } })
  const ref = useRef(null)
  const target = useValue(focusTarget)
  useEffect(() => { if (target === 'checkin') { ref.current?.focus(); focusTarget.set(null) } }, [target])
  const save = useMutation({
    mutationFn: () => ctx.rest('/checkin', { method: 'POST', body: {
      energy: d.energy, valence: d.valence, feeling: d.feeling.trim() || null, body_note: d.body.trim() || null
    } }).then(okOr),
    onSuccess: () => { drafts.set({ ...drafts.get(), checkin: blankCheckin() }); host.notify({ kind: 'success', message: t('checkin.saved') }); onSaved() },
    onError: fail(t('err.checkin'))
  })
  const ready = VALENCES.includes(d.valence) && !save.isPending
  return jsxs('form', { className: 'isc-sec', onSubmit: e => { e.preventDefault(); if (ready) save.mutate() }, children: [
    jsxs('div', { className: 'isc-field', children: [
      jsx('label', { htmlFor: 'isc-energy', children: t('checkin.energy') }),
      jsxs('div', { className: 'isc-range', children: [
        jsx('span', { 'aria-hidden': true, children: t('checkin.low') }),
        jsx('input', { id: 'isc-energy', ref, type: 'range', min: 0, max: 100, step: 1, value: d.energy,
          'aria-valuetext': t('checkin.energyValue', d.energy), onChange: e => set({ energy: Number(e.target.value) }) }),
        jsx('span', { 'aria-hidden': true, children: t('checkin.high') }),
        jsx('output', { htmlFor: 'isc-energy', 'aria-hidden': true, children: d.energy })
      ] })
    ] }),
    jsxs('div', { className: 'isc-field', role: 'group', 'aria-labelledby': 'isc-val-l', children: [
      jsx('span', { id: 'isc-val-l', style: { fontSize: 12.5, fontWeight: 500 }, children: t('checkin.valence') }),
      jsx('div', { className: 'isc-seg', children: jsx(SegmentedControl, { value: d.valence, onChange: v => set({ valence: v }),
        options: VALENCES.map(v => ({ id: v, label: t(`valence.${v}`) })) }) }),
      d.valence ? null : jsx('small', { children: t('checkin.pick') })
    ] }),
    jsxs('div', { className: 'isc-field', children: [
      jsx('label', { htmlFor: 'isc-feel', children: t('checkin.feeling') }),
      jsx(Input, { id: 'isc-feel', value: d.feeling, maxLength: FEELING_MAX, autoComplete: 'off', spellCheck: true, 'aria-describedby': 'isc-feel-h', onChange: e => set({ feeling: e.target.value }) }),
      jsx('small', { id: 'isc-feel-h', children: t('checkin.feelingHint') })
    ] }),
    jsxs('div', { className: 'isc-field', children: [
      jsx('label', { htmlFor: 'isc-body', children: t('checkin.body') }),
      jsx(Textarea, { id: 'isc-body', value: d.body, maxLength: BODY_NOTE_MAX, rows: 2, spellCheck: true, autoCapitalize: 'sentences', 'aria-describedby': 'isc-body-h', onChange: e => set({ body: e.target.value }) }),
      jsx('small', { id: 'isc-body-h', children: t('checkin.bodyHint') })
    ] }),
    jsx('div', { className: 'isc-row', children: jsx(Button, { type: 'submit', disabled: !ready, children: save.isPending ? t('checkin.saving') : t('checkin.save') }) })
  ] })
}

function CoachCard({ t }) {
  const { stuck } = useValue(drafts)
  const busy = !!useValue(transfer)
  const ref = useRef(null)
  const target = useValue(focusTarget)
  useEffect(() => { if (target === 'stuck') { ref.current?.focus(); focusTarget.set(null) } }, [target])
  const go = () => { if (!busy) startCoach(stuck, t) }
  return jsxs('div', { className: 'isc-coach', children: [
    jsxs('div', { className: 'isc-coach-why', children: [
      jsx('p', { children: jsx('b', { children: t('coach.lead') }) }),
      jsx('p', { children: t('coach.body') })
    ] }),
    jsxs('form', { className: 'isc-sec', onSubmit: e => { e.preventDefault(); go() }, children: [
      jsxs('div', { className: 'isc-field', children: [
        jsx('label', { htmlFor: 'isc-stuck', children: t('coach.label') }),
        jsx(Textarea, { id: 'isc-stuck', ref, value: stuck, maxLength: STUCK_MAX, rows: 3, placeholder: t('coach.placeholder'),
          spellCheck: true, autoCapitalize: 'sentences', 'aria-describedby': 'isc-stuck-hint isc-stuck-n',
          onKeyDown: e => { if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') { e.preventDefault(); go() } },
          onChange: e => drafts.set({ ...drafts.get(), stuck: e.target.value }) })
      ] }),
      jsxs('div', { className: 'isc-row', children: [
        jsx(Button, { type: 'submit', disabled: busy, children: busy ? t('coach.opening') : t('coach.go') }),
        jsx('span', { id: 'isc-stuck-n', className: 'isc-hint', children: t('coach.count', stuck.length, STUCK_MAX) })
      ] }),
      jsx('p', { id: 'isc-stuck-hint', className: 'isc-hint', children: t('coach.hint') })
    ] })
  ] })
}

function JournalForm({ ctx, t, onSaved }) {
  const { journal: text, tags } = useValue(drafts)
  const [open, setOpen] = useState(false)
  const ref = useRef(null)
  const target = useValue(focusTarget)
  useEffect(() => { if (target === 'journal') { ref.current?.focus(); focusTarget.set(null) } }, [target])
  const tagList = parseTags(tags)
  const tagsOk = tagList.length <= TAGS_MAX && tagList.every(x => x.length <= TAG_MAX)
  const ready = text.trim().length > 0 && text.length <= JOURNAL_MAX && tagsOk
  return jsxs('div', { className: 'isc-sec isc-journal', children: [
    jsxs('div', { className: 'isc-field', children: [
      jsx('label', { htmlFor: 'isc-journal', className: 'isc-sr', children: t('journal.label') }),
      jsx(Textarea, { id: 'isc-journal', ref, value: text, maxLength: JOURNAL_MAX, placeholder: t('journal.placeholder'),
        spellCheck: true, autoCapitalize: 'sentences', 'aria-describedby': 'isc-journal-n',
        onChange: e => drafts.set({ ...drafts.get(), journal: e.target.value }) })
    ] }),
    jsxs('div', { className: 'isc-field', children: [
      jsx('label', { htmlFor: 'isc-tags', children: t('journal.tags') }),
      jsx(Input, { id: 'isc-tags', value: tags, autoComplete: 'off', 'aria-invalid': tagsOk ? undefined : true, 'aria-describedby': 'isc-tags-h',
        onChange: e => drafts.set({ ...drafts.get(), tags: e.target.value }) }),
      jsx('small', { id: 'isc-tags-h', children: t('journal.tagsHint') })
    ] }),
    jsxs('div', { className: 'isc-row', children: [
      jsx(Button, { disabled: !ready, onClick: () => setOpen(true), children: t('journal.review') }),
      jsx('span', { id: 'isc-journal-n', className: 'isc-hint', children: t('journal.count', text.length, JOURNAL_MAX) })
    ] }),
    jsx(ConfirmDialog, {
      open, onClose: () => setOpen(false),
      title: t('journal.confirmTitle'), description: t('journal.confirmBody'),
      confirmLabel: t('journal.confirm'), busyLabel: t('journal.busy'), doneLabel: t('journal.done'), cancelLabel: t('journal.keep'),
      // Throwing keeps the dialog open with the error shown inline.
      onConfirm: () => ctx.rest('/journal', { method: 'POST', body: { content: text, tags: tagList, confirmed: true } }).then(okOr).then(() => {
        drafts.set({ ...drafts.get(), journal: '', tags: '' })
        host.notify({ kind: 'success', message: t('journal.saved') })
        onSaved()
      }),
      children: jsxs(Fragment, { children: [
        jsx('p', { className: 'isc-dlg-text', tabIndex: 0, children: text }),
        tagList.length ? jsx('p', { className: 'isc-dlg-tags', children: t('journal.tagsLine', tagList) }) : null
      ] })
    })
  ] })
}

function InnerscapePage({ ctx, status, refreshStatus }) {
  const t = useT()
  const qc = useQueryClient()
  const today = useQuery({ queryKey: [ID, 'today'], queryFn: () => ctx.rest('/today'), refetchInterval: 60_000 })
  const s = useValue(status)
  const st = useQuery({ queryKey: [ID, 'status'], queryFn: () => ctx.rest('/status').then(r => { status.set(r); return r }), refetchInterval: 60_000 })
  const refresh = () => { qc.invalidateQueries({ queryKey: [ID] }); refreshStatus() }
  const shell = children => jsx('div', { className: 'isc-host', children: jsx('div', { className: 'isc', children }) })
  const url = s?.base_url || 'http://127.0.0.1:3001'
  const cs = connState(s)

  const head = jsxs('header', { className: 'isc-head', children: [
    jsxs('div', { className: 'isc-mark', children: [
      jsx(Cairn, { size: 40 }),
      jsxs('div', { style: { minWidth: 0 }, children: [
        jsx('h1', { className: 'isc-word', children: t('name') }),
        jsx('p', { className: 'isc-sub', children: t('tagline') })
      ] })
    ] }),
    cs ? jsxs('span', { className: 'isc-conn', 'data-ok': String(cs === 'ok' || cs === 'soon'), role: 'status', 'aria-label': t('conn.label'), children: [
      jsx('i', { 'aria-hidden': true }), cs === 'ok' || cs === 'soon' ? t('conn.up') : t('conn.down')
    ] }) : null
  ] }, 'head')

  const sec = (id, title, hint, body) => jsxs('section', { className: 'isc-card isc-sec', 'aria-labelledby': id, children: [
    jsxs('div', { className: 'isc-sec-head', children: [jsx('h2', { id, className: 'isc-h2', children: title }), hint ? jsx('p', { className: 'isc-hint', children: hint }) : null] }),
    body
  ] }, id)
  // The coach needs no Innerscape server (only parking an item does), so it stays when the server is down.
  const coachSec = sec('isc-coach-h', t('coach.title'), null, jsx(CoachCard, { t }))

  if (!s && st.isError) {
    return shell([head, jsx('div', { className: 'isc-card', role: 'alert', children: jsx(ErrorState, { title: t('err.downTitle'), description: t('err.down'),
      children: jsx(Button, { size: 'sm', variant: 'secondary', onClick: () => st.refetch(), children: t('err.retry') }) }) }, 'err'), coachSec])
  }
  if (!s) {
    return shell([head, jsx(Skeleton, { style: { height: 150, borderRadius: 12 } }, 'a'), jsx(Skeleton, { style: { height: 360, borderRadius: 12 } }, 'b')])
  }

  const warnText = cs === 'token' ? t('err.token') : cs === 'expired' ? t('err.expired') : cs === 'server' ? t('err.server', url) : cs === 'soon' ? t('err.soon') : null
  const warn = warnText ? jsxs('div', { className: 'isc-warn', role: 'alert', children: [
    jsx('span', { children: warnText }),
    jsx(Button, { size: 'sm', variant: 'secondary', onClick: refresh, children: t('err.retry') })
  ] }, 'warn') : null

  return shell([
    head,
    warn,
    sec('isc-today-h', t('today.title'), t('today.hint'), jsx(Today, { q: today, t })),
    coachSec,
    jsxs('div', { className: 'isc-cols', children: [
      sec('isc-checkin-h', t('checkin.title'), t('checkin.hint'), jsx(CheckInForm, { ctx, t, onSaved: refresh })),
      sec('isc-journal-h', t('journal.title'), t('journal.hint'), jsx(JournalForm, { ctx, t, onSaved: refresh }))
    ] }, 'cols'),
    jsxs('footer', { className: 'isc-note', children: [
      jsx('p', { children: jsx('b', { children: t('care.crisis') }) }),
      jsx('p', { children: t('care.privacy', url) })
    ] }, 'note')
  ])
}

// --- status chip -------------------------------------------------------------

function Chip({ prefs }) {
  const t = useT()
  const { showChip } = useValue(prefs)
  if (!showChip) return null
  // Never shows check-ins or counts: the status bar is visible on a shared screen.
  return jsx(Tip, { label: t('chip.open'), children: jsx('button', {
    type: 'button', className: STATUSBAR_BTN, 'aria-label': t('chip.open'), onClick: () => host.navigate(PATH),
    children: jsx(Cairn, { size: 14 })
  }) })
}

// --- settings ----------------------------------------------------------------

function Settings({ prefs, update, status }) {
  const t = useT()
  const { showChip } = useValue(prefs)
  const s = useValue(status)
  const cs = connState(s)
  const tok = cs === 'token' ? t('settings.tokMissing') : cs === 'expired' ? t('settings.tokExpired') : t('settings.tokSet')
  return jsxs('div', { children: [
    jsx(ToggleRow, { label: t('settings.chip'), description: t('settings.chipBody'), checked: showChip, onChange: on => update({ showChip: on }) }),
    jsx(ListRow, { title: t('settings.conn'), description: `${t('settings.connBody', s?.base_url || 'http://127.0.0.1:3001', tok)} ${t('settings.agent')}` }),
    jsx(ListRow, { title: t('settings.privacy'), description: t('settings.privacyBody') })
  ] })
}

// --- register ----------------------------------------------------------------

const DEFAULTS = { showChip: true }

// Stored prefs are untrusted: keep only known keys with valid values.
function cleanPrefs(raw) {
  const p = raw && typeof raw === 'object' ? raw : {}
  return { showChip: typeof p.showChip === 'boolean' ? p.showChip : DEFAULTS.showChip }
}

// Pure helpers, exported for desktop/tests only; the host reads the default export.
export const __internals = { cleanPrefs, connState, parseTags, okOr, drafts, focusTarget, CSS, coachPrompt, handToCoach, startCoach, transfer }

export default {
  id: ID,
  name: 'Innerscape',
  register(ctx) {
    let stored
    try { stored = ctx.storage.get('prefs', {}) } catch { stored = {} }
    const prefs = atom(cleanPrefs(stored))
    const update = patch => { prefs.set(cleanPrefs({ ...prefs.get(), ...patch })); ctx.storage.set('prefs', prefs.get()) }
    ctx.i18n?.register?.(LOCALES)
    const tNow = (key, ...a) => (ctx.i18n?.t ? ctx.i18n.t(key, ...a) : enT(key, ...a))

    const style = document.createElement('style')
    style.dataset.plugin = ID
    style.textContent = CSS
    document.head.appendChild(style)
    ctx.onDispose(() => style.remove())
    // Drafts never outlive the plugin.
    ctx.onDispose(() => { transferSeq++; transfer.set(null); drafts.set(blankDrafts()); focusTarget.set(null) })

    const status = atom(null)
    const pull = () => ctx.rest('/status').then(s => { if (s && typeof s === 'object') status.set(s) }, () => {})
    const go = target => () => { focusTarget.set(target); host.navigate(PATH) }

    ctx.registerMany([
      { id: 'page', area: ROUTES_AREA, data: { path: PATH }, render: () => jsx(InnerscapePage, { ctx, status, refreshStatus: pull }) },
      { id: 'nav', area: SIDEBAR_NAV_AREA, data: { path: PATH, label: tNow('name'), codicon: 'heart' } },
      { id: 'chip', area: STATUSBAR_AREAS.right, order: 110, render: () => jsx(Chip, { prefs }) },
      { id: 'open', area: PALETTE_AREA, data: { id: 'innerscape.open', label: tNow('palette.open'), keywords: ['today', 'mood', 'journal'], run: go(null) } },
      { id: 'checkin', area: PALETTE_AREA, data: { id: 'innerscape.checkin', label: tNow('palette.checkin'), keywords: ['mood', 'energy', 'feeling'], run: go('checkin') } },
      { id: 'journal', area: PALETTE_AREA, data: { id: 'innerscape.journal', label: tNow('palette.journal'), keywords: ['write', 'entry', 'diary'], run: go('journal') } },
      { id: 'unstuck', area: PALETTE_AREA, data: { id: 'innerscape.unstuck', label: tNow('palette.unstuck'), keywords: ['stuck', 'coach', 'overwhelmed', 'next step'], run: go('stuck') } }
    ])

    ctx.registerSettingsPage?.({ id: 'settings', title: tNow('name'), icon: 'heart', render: () => jsx(Settings, { prefs, update, status }) })
  }
}
